     "summary": "10月19日，证监会主席吴清在参加2026金融街论坛年会开幕式时表示，持续深化资本市场包容性改革。聚焦支持新质生产力发展，落实落细“两创板”改革举措，进一步完善科技企业识别筛选等机制。研究推动多层次市场改革，实施更具包容性适应性的发行上市、并购重组等制度。深化再融资改革，择机发布新修订的上市公司证券发行注册管理办法及配套规则。（文章来源：证券时报网）",
